const review = $input.first().json;
const aiResponse = JSON.parse(review.message?.content || review.text || '{}');
return [{
  json: {
    ...items[0].json,
    sentiment: aiResponse.sentiment || 'unknown',
    sentimentScore: aiResponse.score || 0,
    keyThemes: (aiResponse.key_themes || []).join(', '),
    aiSummary: aiResponse.summary || ''
  }
}];

